class Solution {
public:
    vector<int> maxPrimeSubset(int n, int s) {
        // generate primes up to n
        vector<bool> isPrime(n + 1, true);
        if (n >= 0) isPrime[0] = false;
        if (n >= 1) isPrime[1] = false;
        for (int i = 2; i * i <= n; ++i) {
            if (isPrime[i]) {
                for (int j = i * i; j <= n; j += i) isPrime[j] = false;
            }
        }
        vector<int> primes;
        for (int i = 2; i <= n; ++i) if (isPrime[i]) primes.push_back(i);
        int p = (int)primes.size();
        const int INF = 1e9;

        // dp[i][t] = minimal number of primes to reach sum t using primes i..p-1
        vector<vector<int>> dp(p + 1, vector<int>(s + 1, INF));
        dp[p][0] = 0;
        for (int i = p - 1; i >= 0; --i) {
            int val = primes[i];
            for (int t = 0; t <= s; ++t) {
                int best = dp[i + 1][t];                     // skip
                if (t >= val && dp[i + 1][t - val] != INF) { // take
                    best = min(best, dp[i + 1][t - val] + 1);
                }
                dp[i][t] = best;
            }
        }

        // find the largest achievable sum
        int bestSum = 0;
        for (int t = s; t >= 0; --t) {
            if (dp[0][t] != INF) {
                bestSum = t;
                break;
            }
        }
        if (bestSum == 0) return {};

        // reconstruct lexicographically smallest optimal subset
        int need = dp[0][bestSum];
        vector<int> ans;
        int cur = bestSum;
        for (int i = 0; i < p && need > 0; ++i) {
            int val = primes[i];
            if (cur >= val && dp[i + 1][cur - val] == need - 1) {
                ans.push_back(val);
                cur -= val;
                --need;
            }
        }
        return ans;
    }
};
